  def genTestSuite(testCases: ISZ[(Z, ISZ[ST])]): Unit = {
    val tq = "\"\"\""

    val testRoot = Os.path(".") / "src" / "test" / "bridge"

    val CheckLifecycle_battery_assessment_process_check_lifecycle_id = Arch.BatteryStatusAssessmentServiceSystem_Instance_battery_assessment_process_check_lifecycle.id
    val ReportAcquisition_battery_assessment_process_report_acquisition_id = Arch.BatteryStatusAssessmentServiceSystem_Instance_battery_assessment_process_report_acquisition.id
    val ReportQualification_battery_assessment_process_report_qualification_id = Arch.BatteryStatusAssessmentServiceSystem_Instance_battery_assessment_process_report_qualification.id
    val AssessmentDecision_battery_assessment_process_assessment_decision_id = Arch.BatteryStatusAssessmentServiceSystem_Instance_battery_assessment_process_assessment_decision.id
    val ResultCustody_battery_assessment_process_result_custody_id = Arch.BatteryStatusAssessmentServiceSystem_Instance_battery_assessment_process_result_custody.id

    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case CheckLifecycle_battery_assessment_process_check_lifecycle_id =>
          val prefix = "CheckLifecycle_battery_assessment_process_check_lifecycle_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Battery_Status_Assessment_Service")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Battery_Status_Assessment_Service
                |
                |import org.sireum._
                |import scp_candidate.Battery_Status_Assessment_Service._
                |
                |class ${suiteName} extends CheckLifecycle_battery_assessment_process_check_lifecycle_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case ReportAcquisition_battery_assessment_process_report_acquisition_id =>
          val prefix = "ReportAcquisition_battery_assessment_process_report_acquisition_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Battery_Status_Assessment_Service")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Battery_Status_Assessment_Service
                |
                |import org.sireum._
                |import scp_candidate.Battery_Status_Assessment_Service._
                |
                |class ${suiteName} extends ReportAcquisition_battery_assessment_process_report_acquisition_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case ReportQualification_battery_assessment_process_report_qualification_id =>
          val prefix = "ReportQualification_battery_assessment_process_report_qualification_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Battery_Status_Assessment_Service")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.Battery_Status_Assessment_Service
                |
