          println(s"Wrote: ${filename.toUri}")
        case AssessmentDecision_battery_assessment_process_assessment_decision_id =>
          val prefix = "AssessmentDecision_battery_assessment_process_assessment_decision_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","Battery_Status_Assessment_Service")
